def gen(rng):
    def fmt(p):
        return str(len(p)) + '\n' + ' '.join(map(str, p))
    def grow(n):
        # values 1..n placed by growing a window outwards: every k is balanced
        c = rng.randint(0, n - 1)
        lo = hi = c
        order = [c]
        while len(order) < n:
            if lo == 0:
                side = 1
            elif hi == n - 1:
                side = 0
            else:
                side = rng.randint(0, 1)
            if side == 0:
                lo -= 1
                order.append(lo)
            else:
                hi += 1
                order.append(hi)
        p = [0] * n
        for v, i in enumerate(order):
            p[i] = v + 1
        return p
    def perm(n):
        p = list(range(1, n + 1))
        rng.shuffle(p)
        return p
    tests = [fmt([1]), fmt([1, 2]), fmt([2, 1]), fmt([1, 3, 2, 4]), fmt([4, 1, 3, 2]), fmt([2, 3, 1]), fmt([3, 2, 1])]
    for n in (3, 4, 5, 6, 7, 8, 9, 10):
        for _ in range(3):
            tests.append(fmt(perm(n)))
    for n in (5, 8, 12):
        tests.append(fmt(grow(n)))
    for n in (6, 9, 12):
        p = grow(n)
        i, j = rng.randrange(n), rng.randrange(n)
        p[i], p[j] = p[j], p[i]
        tests.append(fmt(p))
    n = 200000
    tests.append(fmt(perm(n)))
    tests.append(fmt(list(range(1, n + 1))))
    tests.append(fmt(list(range(n, 0, -1))))
    tests.append(fmt(grow(n)))
    p = grow(n)
    for _ in range(30):
        i, j = rng.randrange(n), rng.randrange(n)
        p[i], p[j] = p[j], p[i]
    tests.append(fmt(p))
    return tests
